def get_perimeter(cells):
    perimeter = 0
    for x, y in cells:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in cells:
                perimeter += 1
    return perimeter

def get_next_set(cells):
    next_cells = set(cells)
    for x, y in cells:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in cells:
                next_cells.add((nx, ny))
    return next_cells

def simulate(initial_cells, n_steps):
    current_cells = set(initial_cells)
    perimeters = [get_perimeter(current_cells)]
    for _ in range(n_steps):
        current_cells = get_next_set(current_cells)
        perimeters.append(get_perimeter(current_cells))
    return perimeters

# Test different initial sets
# S0 = {(0,0)}
p1 = simulate([(0,0)], 10)
print(f"S0={(0,0)}: {p1}")

# S0 = {(0,0), (1,0)}
p2 = simulate([(0,0), (1,0)], 10)
print(f"S0={(0,0), (1,0)}: {p2}")

# S0 = {(0,0), (1,1)}
p3 = simulate([(0,0), (1,1)], 10)
print(f"S0={(0,0), (1,1)}: {p3}")

# S0 = {(0,0), (2,0)}
p4 = simulate([(0,0), (2,0)], 10)
print(f"S0={(0,0), (2,0)}: {p4}")
